        'titles' => [ 'pl' => 'Zestaw dysz spawalniczych do xTool MetalFab', 'de' => 'Schweißdüsen-Set für xTool MetalFab', 'ru' => 'Комплект сварочных сопел для xTool MetalFab', 'uk' => 'Комплект зварювальних сопел для xTool MetalFab' ],
        'features' => [
            'pl' => [ 'W zestawie: dysza do spawania z drutem, dysza do spawania bez drutu, końcówka do cięcia ręcznego i dysza do ręcznego czyszczenia.', 'Do spawania laserowego, czyszczenia i ręcznego cięcia.', 'Dostępna wersja wtykowa (push-to-connect) i gwintowana – wybierz zgodnie z konstrukcją spawarki.', 'Zestaw zapasowy: spawarka MetalFab ma go już w komplecie.' ],
            'de' => [ 'Enthält eine Schweißdüse mit Draht, eine Schweißdüse ohne Draht, eine Handschneidspitze und eine Handreinigungsdüse.', 'Für Laserschweißen, Reinigen und Handschneiden.', 'Als Steckversion (Push-to-connect) oder mit Gewinde – passend zur Bauart Ihres Schweißgeräts.', 'Ersatzset: Beim MetalFab-Schweißgerät ist es bereits enthalten.' ],
            'ru' => [ 'В комплекте: сопло для сварки с проволокой, сопло для сварки без проволоки, наконечник для ручной резки и сопло для ручной очистки.', 'Для лазерной сварки, очистки и ручной резки.', 'Есть версия с быстрым соединением (push-to-connect) и резьбовая — выбирайте по конструкции аппарата.', 'Запасной комплект: в поставку сварочного аппарата MetalFab он уже входит.' ],
            'uk' => [ 'У комплекті: сопло для зварювання з дротом, сопло для зварювання без дроту, наконечник для ручного різання та сопло для ручного очищення.', 'Для лазерного зварювання, очищення та ручного різання.', 'Є версія зі швидким з’єднанням (push-to-connect) і різьбова — обирайте за конструкцією апарата.', 'Запасний комплект: до постачання зварювального апарата MetalFab він уже входить.' ],
        ],
