    '9098587078869' => [
        'fits' => [ '8974447804629', '9432562729173' ],
        'titles' => [ 'pl' => 'Akcesorium do czyszczenia laserowego MaxClean™ 45 mm do MetalFab', 'de' => 'MaxClean™ 45-mm-Laserreinigungsaufsatz für MetalFab', 'ru' => 'Насадка для лазерной очистки MaxClean™ 45 мм для MetalFab', 'uk' => 'Насадка для лазерного очищення MaxClean™ 45 мм для MetalFab' ],
        'features' => [
            'pl' => [ 'Usuwa rdzę i farbę ze starego metalu, który można potem ponownie wykorzystać – to oszczędność i mniej odpadów.', 'Czyści pas szerokości 45 mm w jednym przejściu zamiast wąskich 15 mm w innych spawarkach laserowych.', 'Laser włącza się dopiero po zetknięciu z obrabianym elementem, a nie z odległości.' ],
            'de' => [ 'Entfernt Rost und Lack von altem Metall, damit Sie es wiederverwenden können – das spart Geld und Abfall.', 'Reinigt 45 mm Breite in einem Durchgang statt schmaler 15 mm wie bei anderen Laserschweißgeräten.', 'Der Laser löst erst bei Kontakt mit dem Werkstück aus, nicht aus der Entfernung.' ],
            'ru' => [ 'Удаляет ржавчину и краску со старого металла, чтобы использовать его повторно, — это экономия и меньше отходов.', 'Очищает полосу шириной 45 мм за один проход вместо узких 15 мм у других лазерных сварочных аппаратов.', 'Лазер включается только при контакте с заготовкой, а не на расстоянии.' ],
            'uk' => [ 'Видаляє іржу й фарбу зі старого металу, щоб використати його повторно, — це економія та менше відходів.', 'Очищає смугу завширшки 45 мм за один прохід замість вузьких 15 мм в інших лазерних зварювальних апаратах.', 'Лазер вмикається лише в разі контакту із заготовкою, а не на відстані.' ],
        ],
    ],
    '9531100168405' => [
        'fits' => [ '8974447804629', '9432562729173' ],
        'titles' => [ 'pl' => 'Podajnik drutu do spawarki xTool MetalFab 1200 W', 'de' => 'Drahtvorschub für das xTool MetalFab 1200-W-Laserschweißgerät', 'ru' => 'Податчик проволоки для xTool MetalFab 1200 Вт', 'uk' => 'Подавач дроту для xTool MetalFab 1200 Вт' ],
        'features' => [
            'pl' => [ 'Pasuje do spawarki laserowej xTool MetalFab 1200 W, nie do modelu 800 W; wersja 1200 W ma już podajnik w zestawie.', 'Drut zmienisz, przełączając przewód między podajnikiem a spawarką, bez wyjmowania szpuli – wygodne przy spawaniu różnych metali.', 'Automatycznie podaje drut z ustawioną prędkością; wystarczy prowadzić pistolet.', 'Obsługuje drut 0,8/1,0/1,2/1,6 mm ze stali nierdzewnej, stali niskowęglowej, aluminium, mosiądzu, tytanu i innych metali.', 'Szpule do 8,5 kg, o grubości do 105 mm i średnicy do 300 mm, wyłącznie z rdzeniem o średnicy 50 mm.' ],
            'de' => [ 'Passt zum xTool MetalFab 1200-W-Laserschweißgerät, nicht zum 800-W-Modell; die 1200-W-Version enthält bereits einen Drahtvorschub.', 'Drahtwechsel durch Umstecken des Kabels zwischen Vorschub und Schweißgerät, ohne die Spule auszubauen – ideal für verschiedene Werkstoffe.', 'Fördert den Draht automatisch mit der eingestellten Geschwindigkeit; Sie führen nur die Schweißpistole.', 'Für Draht mit 0,8/1,0/1,2/1,6 mm aus Edelstahl, Baustahl, Aluminium, Messing, Titan und mehr.', 'Spulen bis 8,5 kg, bis 105 mm breit und bis 300 mm Außendurchmesser, nur mit 50 mm Kerndurchmesser.' ],
            'ru' => [ 'Подходит к лазерному сварочному аппарату xTool MetalFab 1200 Вт, но не к модели 800 Вт; версия 1200 Вт уже комплектуется податчиком.', 'Проволоку можно сменить, переключив кабель между податчиком и аппаратом, не снимая катушку, — удобно при сварке разных металлов.', 'Автоматически подаёт проволоку с заданной скоростью — достаточно вести горелку.', 'Поддерживает проволоку 0,8/1,0/1,2/1,6 мм из нержавеющей и низкоуглеродистой стали, алюминия, латуни, титана и других металлов.', 'Катушки массой до 8,5 кг, толщиной до 105 мм и диаметром до 300 мм, только с сердечником 50 мм.' ],
            'uk' => [ 'Підходить до лазерного зварювального апарата xTool MetalFab 1200 Вт, але не до моделі 800 Вт; версія 1200 Вт уже має подавач у комплекті.', 'Дріт можна змінити, перемкнувши кабель між подавачем і апаратом, не знімаючи котушку, — зручно для зварювання різних металів.', 'Автоматично подає дріт із заданою швидкістю — досить вести пальник.', 'Підтримує дріт 0,8/1,0/1,2/1,6 мм із нержавної та низьковуглецевої сталі, алюмінію, латуні, титану й інших металів.', 'Котушки вагою до 8,5 кг, завтовшки до 105 мм і діаметром до 300 мм, лише з осердям 50 мм.' ],
        ],
    ],
