    '8978403950805' => [
        'fits' => [ '8974447804629', '9432562729173' ],
        'titles' => [ 'pl' => 'Samościemniająca przyłbica spawalnicza 1080 nm do MetalFab', 'de' => 'Automatik-Laserschweißhelm 1080 nm für MetalFab', 'ru' => 'Сварочная маска-хамелеон 1080 нм для MetalFab', 'uk' => 'Зварювальна маска-хамелеон 1080 нм для MetalFab' ],
        'features' => [
            'pl' => [ 'Filtry chroniące przed laserem 1060–1090 nm, do OD 8+, dopasowane do xTool MetalFab.', 'Samościemniający filtr z dwoma czujnikami dopasowuje przyciemnienie do światła otoczenia.', 'Duże okno 8 × 10 cm i klasa optyczna 1/1/1/1 zapewniają szerokie pole widzenia w naturalnych barwach.', 'Waży 560 g, ma trzy pokrętła regulacji i odchyla się o 180°.', 'Baterie (2 × 3 V, guzikowe) kupuje się osobno; zalecane ustawienie GRIND to 5–9.' ],
            'de' => [ 'Laserschutzfilter für 1060–1090 nm bis OD 8+, abgestimmt auf den xTool MetalFab.', 'Der automatisch abdunkelnde Filter mit zwei Sensoren passt die Tönung an das Umgebungslicht an.', 'Großes Sichtfeld von 8 × 10 cm mit optischer Klasse 1/1/1/1 und farbechter Sicht.', '560 g leicht, mit drei Einstellknöpfen und um 180° hochklappbar.', 'Batterien (2 × 3-V-Knopfzellen) separat erforderlich; empfohlene GRIND-Einstellung 5–9.' ],
            'ru' => [ 'Защитные светофильтры для лазера 1060–1090 нм до OD 8+, подходят к xTool MetalFab.', 'Автоматически затемняющийся фильтр с двумя датчиками подстраивает затемнение под окружающий свет.', 'Большое окно 8 × 10 см и оптический класс 1/1/1/1 дают широкий обзор в естественных цветах.', 'Весит 560 г, имеет три регулятора и откидывается на 180°.', 'Батарейки (2 × 3 В, таблеточные) приобретаются отдельно; рекомендуемая настройка GRIND — 5–9.' ],
            'uk' => [ 'Захисні світлофільтри для лазера 1060–1090 нм до OD 8+, підходять до xTool MetalFab.', 'Самозатемнювальний фільтр із двома датчиками підлаштовує затемнення під навколишнє світло.', 'Велике вікно 8 × 10 см та оптичний клас 1/1/1/1 дають широкий огляд у природних кольорах.', 'Важить 560 г, має три регулятори та відкидається на 180°.', 'Батарейки (2 × 3 В, таблеткові) купують окремо; рекомендоване налаштування GRIND — 5–9.' ],
