        'titles' => [ 'pl' => 'Rękawice do spawania laserowego xTool MetalFab (35,56 cm)', 'de' => 'Laserschweißhandschuhe für xTool MetalFab (35,56 cm)', 'ru' => 'Перчатки для лазерной сварки xTool MetalFab (35,56 см)', 'uk' => 'Рукавиці для лазерного зварювання xTool MetalFab (35,56 см)' ],
        'features' => [
            'pl' => [ 'Wykonane ze skóry koziej licowej i dwoiny bydlęcej, z miękką polarową podszewką.', 'Szwy z ognioodpornego kevlaru; producent podaje zgodność z normami EN 388 i EN 407.', 'Chronią przed wysoką temperaturą, iskrami i odpryskami do ok. 300 °C; nie trzymaj w nich długo gorącego metalu.', 'Wzmocnienia na dłoni i palcach; standardowy rozmiar XL (17 × 35 cm).', 'Dopasowane do spawarki laserowej i wycinarki CNC xTool MetalFab.' ],
            'de' => [ 'Aus Ziegennarbenleder und Rindspaltleder mit weichem Fleecefutter.', 'Nähte aus feuerfestem Kevlar; laut Hersteller nach EN 388 und EN 407.', 'Schützen vor Hitze, Funken und Spritzern bis etwa 300 °C; heißes Metall nicht lange festhalten.', 'Verstärkte Handflächen und Finger; Standardgröße XL (17 × 35 cm).', 'Abgestimmt auf das xTool MetalFab Laserschweißgerät und den CNC-Schneider.' ],
            'ru' => [ 'Из лицевой козьей кожи и коровьего спилка с мягкой флисовой подкладкой.', 'Швы из огнестойкого кевлара; производитель заявляет соответствие EN 388 и EN 407.', 'Защищают от высокой температуры, искр и брызг примерно до 300 °C; не держите в них горячий металл долго.', 'Усиленные ладони и пальцы; стандартный размер XL (17 × 35 см).', 'Подходят к лазерному сварочному аппарату и ЧПУ-резаку xTool MetalFab.' ],
            'uk' => [ 'З лицьової козячої шкіри та коров’ячого спилку з м’якою флісовою підкладкою.', 'Шви з вогнестійкого кевлару; виробник заявляє відповідність EN 388 і EN 407.', 'Захищають від високої температури, іскор і бризок приблизно до 300 °C; не тримайте в них гарячий метал довго.', 'Посилені долоні та пальці; стандартний розмір XL (17 × 35 см).', 'Підходять до лазерного зварювального апарата та ЧПК-різака xTool MetalFab.' ],
