    '8987317993685' => [
        'fits' => [ '8974447804629' ],
        'titles' => [ 'pl' => 'Dysza czyszcząca do wycinarki CNC xTool MetalFab', 'de' => 'Reinigungsdüse für den xTool MetalFab CNC-Schneider', 'ru' => 'Очищающее сопло для ЧПУ-резака xTool MetalFab', 'uk' => 'Очищувальне сопло для ЧПК-різака xTool MetalFab' ],
        'features' => [
            'pl' => [ 'Automatycznie usuwa rdzę i farbę.', 'Montuje się ją w wycinarce CNC MetalFab; do ręcznego czyszczenia spawarką służy osobna dysza.', 'Wersja wtykowa (push-to-connect) lub gwintowana – zgodnie z konstrukcją spawarki.', 'Dysza zapasowa: zestaw MetalFab zawiera już dyszę czyszczącą CNC.' ],
            'de' => [ 'Entfernt Rost und Lack automatisch.', 'Wird im MetalFab CNC-Schneider montiert; für die Handreinigung mit dem Schweißgerät gibt es eine eigene Düse.', 'Als Steckversion (Push-to-connect) oder mit Gewinde – passend zur Bauart des Schweißgeräts.', 'Ersatzdüse: Im MetalFab-Paket ist bereits eine CNC-Reinigungsdüse enthalten.' ],
            'ru' => [ 'Автоматически удаляет ржавчину и краску.', 'Устанавливается в ЧПУ-резак MetalFab; для ручной очистки сварочным аппаратом есть отдельное сопло.', 'Версия с быстрым соединением (push-to-connect) или резьбовая — по конструкции аппарата.', 'Запасное сопло: в комплект MetalFab очищающее сопло ЧПУ уже входит.' ],
            'uk' => [ 'Автоматично видаляє іржу й фарбу.', 'Встановлюється в ЧПК-різак MetalFab; для ручного очищення зварювальним апаратом є окреме сопло.', 'Версія зі швидким з’єднанням (push-to-connect) або різьбова — за конструкцією апарата.', 'Запасне сопло: до комплекту MetalFab очищувальне сопло ЧПК уже входить.' ],
        ],
    ],
    '8987311964373' => [
        'fits' => [ '8974447804629' ],
        'titles' => [ 'pl' => 'Standardowe dysze tnące do wycinarki CNC xTool MetalFab (5 szt.)', 'de' => 'Standard-Schneiddüsen für den xTool MetalFab CNC-Schneider (5 Stk.)', 'ru' => 'Стандартные режущие сопла для ЧПУ-резака xTool MetalFab (5 шт.)', 'uk' => 'Стандартні різальні сопла для ЧПК-різака xTool MetalFab (5 шт.)' ],
        'features' => [
            'pl' => [ 'Do precyzyjnego cięcia stali nierdzewnej, mosiądzu, aluminium, blachy ocynkowanej i stali węglowej.', 'Metale cieńsze niż 1 mm tnie przy ciśnieniu gazu tylko 0,6 MPa.', 'Grubszą stal nierdzewną, mosiądz i aluminium tnie przy 1,2 MPa; alternatywą jest dysza SaveGas™ przy 0,6 MPa.', 'Do stali węglowej i blachy ocynkowanej od 2 mm użyj dyszy dwuwarstwowej i tlenu.', 'Zestaw zapasowy: wycinarka CNC MetalFab ma już standardową dyszę w komplecie.' ],
            'de' => [ 'Für präzise Schnitte in Edelstahl, Messing, Aluminium, verzinktem Blech und Kohlenstoffstahl.', 'Metalle unter 1 mm schneidet sie mit nur 0,6 MPa Gasdruck.', 'Dickeren Edelstahl, Messing und Aluminium schneidet sie mit 1,2 MPa; alternativ die SaveGas™-Düse mit 0,6 MPa.', 'Für Kohlenstoffstahl und verzinktes Blech ab 2 mm die Doppelschichtdüse und Sauerstoff verwenden.', 'Ersatzset: Beim MetalFab CNC-Schneider ist bereits eine Standarddüse enthalten.' ],
            'ru' => [ 'Для точной резки нержавеющей стали, латуни, алюминия, оцинкованной и углеродистой стали.', 'Металл тоньше 1 мм режет при давлении газа всего 0,6 МПа.', 'Более толстую нержавеющую сталь, латунь и алюминий режет при 1,2 МПа; альтернатива — сопло SaveGas™ при 0,6 МПа.', 'Для углеродистой и оцинкованной стали от 2 мм используйте двухслойное сопло и кислород.', 'Запасной комплект: стандартное сопло уже входит в поставку ЧПУ-резака MetalFab.' ],
            'uk' => [ 'Для точного різання нержавної сталі, латуні, алюмінію, оцинкованої та вуглецевої сталі.', 'Метал, тонший за 1 мм, ріже за тиску газу лише 0,6 МПа.', 'Товстішу нержавну сталь, латунь і алюміній ріже за 1,2 МПа; альтернатива — сопло SaveGas™ за 0,6 МПа.', 'Для вуглецевої та оцинкованої сталі від 2 мм використовуйте двошарове сопло й кисень.', 'Запасний комплект: стандартне сопло вже входить до постачання ЧПК-різака MetalFab.' ],
        ],
    ],
    '8987271725269' => [
        'fits' => [ '8974447804629' ],
        'titles' => [ 'pl' => 'Zestaw dysz tnących SaveGas™ do wycinarki CNC xTool MetalFab', 'de' => 'SaveGas™-Schneiddüsen-Set für den xTool MetalFab CNC-Schneider', 'ru' => 'Комплект сопел SaveGas™ для ЧПУ-резака xTool MetalFab', 'uk' => 'Комплект сопел SaveGas™ для ЧПК-різака xTool MetalFab' ],
        'features' => [
            'pl' => [ 'W zestawie teleskopowa dysza tnąca SaveGas™ i 10 zapasowych pierścieni ceramicznych.', 'Tnie stal nierdzewną 4 mm, aluminium 4 mm i mosiądz 3 mm przy ciśnieniu powietrza tylko 0,6 MPa (87 PSI).', 'Najmniejszy wycinany detal to 2,5 mm, a bardzo drobne wzory mogą mieć zadziory.', 'Cięcie kontaktowe może zarysować powierzchnię; do cięć bez rys wybierz dyszę standardową.', 'Zestaw zapasowy: wycinarka CNC MetalFab ma go już w komplecie.' ],
            'de' => [ 'Enthält eine teleskopische SaveGas™-Schneiddüse und 10 Ersatz-Keramikringe.', 'Schneidet 4 mm Edelstahl, 4 mm Aluminium und 3 mm Messing mit nur 0,6 MPa (87 PSI) Luftdruck.', 'Die kleinste Schnittkontur beträgt 2,5 mm; sehr filigrane Motive sind eventuell nicht gratfrei.', 'Kontaktschnitt kann die Oberfläche zerkratzen; für kratzfreie Schnitte die Standarddüse wählen.', 'Ersatzset: Beim MetalFab CNC-Schneider ist es bereits enthalten.' ],
            'ru' => [ 'В комплекте телескопическое режущее сопло SaveGas™ и 10 запасных керамических колец.', 'Режет нержавеющую сталь 4 мм, алюминий 4 мм и латунь 3 мм при давлении воздуха всего 0,6 МПа (87 PSI).', 'Минимальный размер вырезаемого элемента — 2,5 мм, очень мелкие узоры могут получиться с заусенцами.', 'Контактная резка может поцарапать поверхность; для резов без царапин выберите стандартное сопло.', 'Запасной комплект: он уже входит в поставку ЧПУ-резака MetalFab.' ],
            'uk' => [ 'У комплекті телескопічне різальне сопло SaveGas™ і 10 запасних керамічних кілець.', 'Ріже нержавну сталь 4 мм, алюміній 4 мм і латунь 3 мм за тиску повітря лише 0,6 МПа (87 PSI).', 'Мінімальний розмір вирізуваного елемента — 2,5 мм, дуже дрібні візерунки можуть мати задирки.', 'Контактне різання може подряпати поверхню; для різів без подряпин оберіть стандартне сопло.', 'Запасний комплект: він уже входить до постачання ЧПК-різака MetalFab.' ],
        ],
    ],
