    '8973412073685' => [
        'fits' => [ '8974447804629' ],
        'titles' => [ 'pl' => 'Kompresor z osuszaczem xTool Selected do wycinarki CNC MetalFab', 'de' => 'xTool Selected Kompressor mit Lufttrockner für MetalFab CNC-Schneider', 'ru' => 'Компрессор с осушителем xTool Selected для ЧПУ-резака MetalFab', 'uk' => 'Компресор з осушувачем xTool Selected для ЧПК-різака MetalFab' ],
        'features' => [
            'pl' => [ 'Z dyszą SaveGas™ tnie bez zadziorów stal nierdzewną 4 mm, aluminium 4 mm i mosiądz 3 mm przy 6 barach.', 'Zamiast drogiego azotu lub argonu tnie się zwykłym powietrzem – według xTool to ponad 20 000 € oszczędności rocznie.', 'Trzystopniowa filtracja HyperPure™ usuwa 99,999% oleju i rdzy oraz 99,99% wilgoci ze sprężonego powietrza.', 'Zajmuje tylko 0,066 m³.', 'Ciśnienie do 10 bar, przepływ 14,1 CFM, silnik 5,2 KM i stabilna praca od -10 °C do 40 °C.' ],
            'de' => [ 'Mit der SaveGas™-Düse gratfreie Schnitte in 4 mm Edelstahl, 4 mm Aluminium und 3 mm Messing bei 6 bar.', 'Statt teurem Stickstoff oder Argon schneiden Sie mit Luft – laut xTool über 20.000 € Ersparnis pro Jahr.', 'Die dreistufige HyperPure™-Filterung entfernt 99,999 % Öl und Rost sowie 99,99 % Feuchtigkeit aus der Druckluft.', 'Braucht nur 0,066 m³ Platz.', 'Bis 10 bar, 14,1 CFM Luftstrom, 5,2 PS Motorleistung und stabiler Betrieb von -10 °C bis 40 °C.' ],
            'ru' => [ 'С соплом SaveGas™ режет без заусенцев нержавеющую сталь 4 мм, алюминий 4 мм и латунь 3 мм при 6 бар.', 'Вместо дорогого азота или аргона используется обычный воздух — по данным xTool, экономия более 20 000 € в год.', 'Трёхступенчатая фильтрация HyperPure™ удаляет из сжатого воздуха 99,999% масла и ржавчины и 99,99% влаги.', 'Занимает всего 0,066 м³.', 'Давление до 10 бар, поток 14,1 CFM, мощность двигателя 5,2 л. с., стабильная работа от -10 °C до 40 °C.' ],
            'uk' => [ 'Із соплом SaveGas™ ріже без задирок нержавну сталь 4 мм, алюміній 4 мм і латунь 3 мм за 6 бар.', 'Замість дорогого азоту чи аргону використовується звичайне повітря — за даними xTool, економія понад 20 000 € на рік.', 'Триступенева фільтрація HyperPure™ видаляє зі стисненого повітря 99,999% оливи та іржі й 99,99% вологи.', 'Займає лише 0,066 м³.', 'Тиск до 10 бар, потік 14,1 CFM, потужність двигуна 5,2 к. с., стабільна робота від -10 °C до 40 °C.' ],
        ],
    ],
    '8976176087253' => [
        'fits' => [ '8974447804629' ],
        'titles' => [ 'pl' => 'Osuszacz powietrza xTool Selected do wycinarki CNC MetalFab', 'de' => 'xTool Selected Lufttrockner für den MetalFab CNC-Schneider', 'ru' => 'Осушитель воздуха xTool Selected для ЧПУ-резака MetalFab', 'uk' => 'Осушувач повітря xTool Selected для ЧПК-різака MetalFab' ],
        'features' => [
            'pl' => [ 'Trzystopniowa filtracja HyperPure™ usuwa ze sprężonego powietrza 99,999% oleju i rdzy oraz 99,99% wilgoci, co poprawia jakość cięcia.', 'Działa wyłącznie z kompresorem powietrza.', 'Przy własnym kompresorze przepływ musi być niższy niż 14,1 CFM (400 l/min), ciśnienie niższe niż 12,5 bar (1,25 MPa), a temperatura powietrza niższa niż 50 °C.', 'Przekroczenie tych wartości może uszkodzić osuszacz i pogorszyć cięcie.' ],
            'de' => [ 'Die dreistufige HyperPure™-Filterung entfernt 99,999 % Öl und Rost sowie 99,99 % Feuchtigkeit aus der Druckluft für beste Schnittergebnisse.', 'Nur zusammen mit einem Luftkompressor verwendbar.', 'Bei eigenem Kompressor: Luftstrom unter 14,1 CFM (400 l/min), Druck unter 12,5 bar (1,25 MPa) und Lufttemperatur unter 50 °C.', 'Höhere Werte können den Trockner beschädigen und das Schnittergebnis verschlechtern.' ],
            'ru' => [ 'Трёхступенчатая фильтрация HyperPure™ удаляет из сжатого воздуха 99,999% масла и ржавчины и 99,99% влаги для лучшего качества резки.', 'Работает только вместе с воздушным компрессором.', 'При использовании своего компрессора поток должен быть ниже 14,1 CFM (400 л/мин), давление — ниже 12,5 бар (1,25 МПа), температура воздуха — ниже 50 °C.', 'Превышение этих значений может повредить осушитель и ухудшить резку.' ],
            'uk' => [ 'Триступенева фільтрація HyperPure™ видаляє зі стисненого повітря 99,999% оливи та іржі й 99,99% вологи для кращої якості різання.', 'Працює лише разом із повітряним компресором.', 'Із власним компресором потік має бути нижчим за 14,1 CFM (400 л/хв), тиск — нижчим за 12,5 бар (1,25 МПа), температура повітря — нижчою за 50 °C.', 'Перевищення цих значень може пошкодити осушувач і погіршити різання.' ],
        ],
    ],

    // O1 Omni Printer
    '9477184782549' => [
        'fits' => [ '9475369337045' ],
        'titles' => [ 'pl' => 'Przystawka obrotowa xTool OR1 do O1 Omni Printer', 'de' => 'xTool OR1 Rotationsaufsatz für O1 Omni Printer', 'ru' => 'Ротационная насадка xTool OR1 для O1 Omni Printer', 'uk' => 'Ротаційна насадка xTool OR1 для O1 Omni Printer' ],
        'features' => [
            'pl' => [ 'Druk na popularnych kubkach, puszkach, ozdobach, małych kulach i innych zakrzywionych przedmiotach.', 'Pixel-Scan™ i obrazowanie CIS tworzą podgląd 1:1 do dokładnego pozycjonowania.', 'Obrót 360° ze sterowaniem kątem daje precyzyjny nadruk dookoła bez ręcznego mierzenia.', 'Wykrywa uchwyty, pozwala oznaczyć strefy bez nadruku i automatycznie poziomuje kubki o nieregularnym kształcie.', 'Efekty tekstury, wytłoczenia i fluorescencji na zakrzywionych produktach.' ],
            'de' => [ 'Druckt auf beliebte Becherformen, Dosen, Ornamente, kleine Kugeln und mehr.', 'Pixel-Scan™ und CIS-Bildgebung erzeugen eine 1:1-Vorschau für genaue Platzierung.', 'Winkelgesteuerte 360°-Drehung für präzise Rundumdrucke ohne manuelles Messen.', 'Erkennt Henkel, markiert druckfreie Bereiche und nivelliert unebene Becherformen automatisch.', 'Textur-, Präge- und Fluoreszenzeffekte für gewölbte Produkte.' ],
            'ru' => [ 'Печать на популярных кружках, банках, украшениях, небольших шарах и других изогнутых предметах.', 'Pixel-Scan™ и CIS-сканирование создают предпросмотр 1:1 для точного размещения.', 'Вращение на 360° с контролем угла даёт точную печать по кругу без ручных замеров.', 'Распознаёт ручки, позволяет отметить зоны без печати и автоматически выравнивает кружки неровной формы.', 'Эффекты текстуры, рельефа и флуоресценции на изогнутых изделиях.' ],
