    '8762129842389' => [
        'fits' => [ '9089720189141', '15473430692053', '15452856942805', '8169201631445', '9163846877397', '9009695293653', '9187692970197', '8523126931669', '8974447804629', '9573828133077', '8941086245077' ],
        'titles' => [ 'pl' => 'Oczyszczacz powietrza xTool SafetyPro™ AP2 / AP2 Max', 'de' => 'xTool SafetyPro™ AP2 / AP2 Max Luftreiniger', 'ru' => 'Очиститель воздуха xTool SafetyPro™ AP2 / AP2 Max', 'uk' => 'Очищувач повітря xTool SafetyPro™ AP2 / AP2 Max' ],
        'features' => [
            'pl' => [ 'Dwie wersje: AP2 o wydajności 150 m³/h do laserów biurkowych i AP2 Max o wydajności 700 m³/h do przemysłowych wycinarek laserowych.', 'Do 7 warstw filtracji usuwa 99,97% cząstek; AP2 Max ma dodatkowo filtr formaldehydu.', 'AP2 Max ma 4 razy większą pojemność filtrów, więc rzadziej trzeba je wymieniać.', 'Separacja cyklonowa wychwytuje duże cząstki i wydłuża żywotność filtra wstępnego 10-krotnie.', 'Automatyczne włączanie i wyłączanie, synchronizacja z laserami xTool i ustawienia dopasowane do materiału.' ],
            'de' => [ 'Zwei Leistungsstufen: AP2 mit 150 m³/h für Desktop-Laser und AP2 Max mit 700 m³/h für industrielle Laserschneider.', 'Bis zu 7 Filterstufen entfernen 99,97 % der Partikel; der AP2 Max hat zusätzlich einen Formaldehydfilter.', 'Der AP2 Max bietet 4-fache Filterkapazität und damit seltenere Filterwechsel.', 'Die Zyklonabscheidung fängt große Partikel ab und verlängert die Lebensdauer des Vorfilters um das 10-Fache.', 'Automatisches Ein- und Ausschalten, Synchronisierung mit xTool-Lasern und passende Einstellungen für jedes Material.' ],
            'ru' => [ 'Две версии: AP2 производительностью 150 м³/ч для настольных лазеров и AP2 Max производительностью 700 м³/ч для промышленных лазерных резаков.', 'До 7 ступеней фильтрации удаляют 99,97% частиц; у AP2 Max есть дополнительный фильтр от формальдегида.', 'У AP2 Max в 4 раза больше ёмкость фильтров, поэтому их меняют реже.', 'Циклонная сепарация улавливает крупные частицы и продлевает срок службы предфильтра в 10 раз.', 'Автоматическое включение и выключение, синхронизация с лазерами xTool и настройки под каждый материал.' ],
            'uk' => [ 'Дві версії: AP2 продуктивністю 150 м³/год для настільних лазерів і AP2 Max продуктивністю 700 м³/год для промислових лазерних різаків.', 'До 7 ступенів фільтрації видаляють 99,97% частинок; AP2 Max має додатковий фільтр від формальдегіду.', 'AP2 Max має в 4 рази більшу ємність фільтрів, тож їх замінюють рідше.', 'Циклонна сепарація вловлює великі частинки й подовжує термін служби передфільтра в 10 разів.', 'Автоматичне вмикання й вимикання, синхронізація з лазерами xTool і налаштування під кожен матеріал.' ],
        ],
    ],
