        'titles' => [ 'pl' => 'Filtry do oczyszczacza xTool SafetyPro™ AP2', 'de' => 'Filter für den xTool SafetyPro™ AP2 Luftreiniger', 'ru' => 'Фильтры для очистителя воздуха xTool SafetyPro™ AP2', 'uk' => 'Фільтри для очищувача повітря xTool SafetyPro™ AP2' ],
        'features' => [
            'pl' => [ 'Filtry zamienne do oczyszczacza SafetyPro™ AP2: wstępny, średniej skuteczności, warstwa węgla aktywnego, gęsta siatka węglowa i filtr wysokiej skuteczności.', 'Każdy filtr ma inną żywotność – od 100 do 600 godzin pracy.', 'Gęsta siatka węglowa i filtr z węglem aktywnym pochłaniają szkodliwe gazy i zapachy.', 'Filtr cyklonowy jest wielokrotnego użytku – wystarczy go wyczyścić.' ],
